class Solution {
    public List<Integer> eventualSafeNodes(int[][] graph){
        int[] color=new int[graph.length];
        List<Integer> answer=new ArrayList<>();
        for(int node=0;node<graph.length;node++)if(safe(node,graph,color))answer.add(node);
        return answer;
    }
    private boolean safe(int node,int[][] graph,int[] color){
        if(color[node]!=0)return color[node]==2;
        color[node]=1;
        for(int next:graph[node])if(!safe(next,graph,color)){
            color[node]=3;
            return false;
        }
        color[node]=2;
        return true;
    }
}

